# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config[env_key] = _coerce_value(value, defaults.get(env_key))
    return config

def _coerce_value(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ('true', '1', 'yes')
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_toml_file():
    defaults = {'key': 'value'}
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'key': 'value'}

def test_env_variables():
    defaults = {'key': 'value'}
    config = load_config(defaults, env_prefix='APP', env_mapping={'APP__KEY': 'new_value'})
    assert config == {'key': 'new_value'}

def test_coercion():
    defaults = {'int_key': 1, 'float_key': 1.0, 'bool_key': True, 'str_key': 'string'}
    config = load_config(defaults, env_mapping={'APP__INT_KEY': '2', 'APP__FLOAT_KEY': '2.0', 'APP__BOOL_KEY': 'false', 'APP__STR_KEY': 'new_string'})
    assert config == {'int_key': 2, 'float_key': 2.0, 'bool_key': False, 'str_key': 'new_string'}

def test_error_handling():
    defaults = {'key': 'value'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_mapping={'APP__KEY': 'invalid_value'})

